`default_nettype none

module player_button #(
    parameter MAX_POS = 16
)(
    input  wire clk,
    input  wire btn,
    input  wire [1:0] current_screen,
    input  wire reset,
    output reg [$clog2(MAX_POS)-1:0] cur_pos,
    output wire activity,
    output reg  ready_to_play
);

    localparam WAIT_INTERACT   = 2'd0;
    localparam WHEN_BTN        = 2'd1;
    localparam WAIT_RELEASE_BTN= 2'd2;
    localparam WHEN_RESET      = 2'd3;
    reg [1:0] state;

    always @(posedge clk) begin
      if (reset) begin
        state <= 2'd0;
        cur_pos <= 0;
        ready_to_play <= 1'b0;

      end else begin
        case (state)
            WAIT_INTERACT: begin
                if (btn)
                    state <= WHEN_BTN;
                else if (reset)
                    state <= WHEN_RESET;
            end

            WHEN_BTN: begin
                state <= WAIT_RELEASE_BTN;
                if (current_screen == 2'b00)
                    ready_to_play <= 1;
                else if (current_screen == 2'b01 && ready_to_play)
                    cur_pos <= cur_pos + 1'd1;
            end

            WAIT_RELEASE_BTN: begin
                if (!btn)
                    state <= WAIT_INTERACT;
            end

            WHEN_RESET: begin
                state <= WAIT_INTERACT;
                cur_pos <= 0;
                ready_to_play <= 0;
            end
        endcase
      end
    end

    assign activity = btn;

endmodule

files.src/button-debouncer/button_debouncer.v:
`default_nettype none

module button_debouncer #(
    parameter DEBOUNCE_CLK_CNT = 65536
)(
    input  wire clk,
    input  wire reset,
    input  wire btn_in,
    output reg  btn_debounced = 1'b0
);
    localparam CNT_WIDTH = (DEBOUNCE_CLK_CNT > 1) ? $clog2(DEBOUNCE_CLK_CNT) : 1;

    localparam [CNT_WIDTH-1:0] DEBOUNCE_CNT_MAX = DEBOUNCE_CLK_CNT[CNT_WIDTH-1:0];
    localparam [CNT_WIDTH-1:0] DEBOUNCE_LIMIT   = DEBOUNCE_CNT_MAX - 1'b1;

    reg [$clog2(DEBOUNCE_CLK_CNT)-1:0] cnt = 0;

    always @(posedge clk) begin
        if (reset) begin
            cnt <= 0;
            btn_debounced <= 1'b0;
        end else begin
            if (btn_in == 1'b0) begin
                cnt <= 0;
                btn_debounced <= 1'b0;
            end else begin
                if (cnt < DEBOUNCE_LIMIT)
                    cnt <= cnt + 1'd1;
                else
                    btn_debounced <= 1'b1;
            end
        end
    end

endmodule

files.src/WS2812B-driver/WS2812B_driver.v:
`default_nettype none

module WS2812B_driver #(
    parameter MAX_POS = 16
)(
    input  wire clk,
    input  wire reset,
    output reg  leds_line = 1'b0,
    input  wire update_frame,
    output reg [$clog2(MAX_POS)-1:0] program_led_number = 0,
    input  wire [7:0] program_red_intensity,
    input  wire [7:0] program_blue_intensity,
    input  wire [7:0] program_green_intensity
);

    localparam step_max = 62;
    localparam bit_proceed_max = 23;
    localparam [1:0] WaitTrigger = 2'b00;
    localparam [1:0] SendLEDsData = 2'b01;
    localparam [1:0] ValidateSeq = 2'b10;
    localparam [1:0] WaitTriggerRelease = 2'b11;

    reg [$clog2(step_max)-1:0] step = 0;
    reg [$clog2(bit_proceed_max)-1:0] bit_proceed = 0;
    reg [$clog2(2600)-1:0] reset_step = 0;
    reg [1:0] stage = WaitTrigger;
    reg seq_trigger;
    reg seq_bit_to_code;

    wire seq_line;  // <--- ajout d’un fil intermédiaire

    wire [23:0] data_concat = {program_green_intensity, program_red_intensity, program_blue_intensity};

    NRZ_sequence #(
        .DURATION_CLK_COUNTS(62),
        .CODE_1_HIGH_DURATION_CLK_COUNTS(39),
        .CODE_0_HIGH_DURATION_CLK_COUNTS(19)
    ) NRZ_sequence_inst (
        .clk(clk),
        .reset(reset),
        .trigger(seq_trigger),
        .bit_to_code(seq_bit_to_code),
        .seq(seq_line)   // <--- on connecte ici le wire
    );

    always @(posedge clk) begin

        if (reset) begin
            seq_trigger <= 1'b0;
            seq_bit_to_code <= 0;
            stage <= WaitTrigger;
            step <= 0;
            bit_proceed <= 0;
            reset_step <= 0;
            leds_line <= 0;

        end else begin
          leds_line <= seq_line;

          case (stage)
              WaitTrigger: begin
                  if (update_frame == 1'b1) begin
                      seq_trigger <= 1'b1;
                      seq_bit_to_code <= data_concat[bit_proceed_max - bit_proceed];
                      stage <= SendLEDsData;
                  end else begin
                      seq_trigger <= 1'b0;
                  end
              end

              SendLEDsData: begin
                  if (seq_trigger == 1'b1)
                      seq_trigger <= 1'b0;

                  if (step == step_max) begin
                      step <= 0;
                      if (bit_proceed == bit_proceed_max) begin
                          bit_proceed <= 0;
                          if (program_led_number == MAX_POS - 1) begin
                              program_led_number <= 0;
                              stage <= ValidateSeq;
                          end else begin
                              program_led_number <= program_led_number + 1'd1;
                              seq_bit_to_code <= data_concat[bit_proceed_max];
                              seq_trigger <= 1'b1;
                          end
                      end else begin
                          seq_trigger <= 1'b1;
                          bit_proceed <= bit_proceed + 1'd1;
                          seq_bit_to_code <= data_concat[bit_proceed_max - (bit_proceed + 1)];
                      end
                  end else begin
                      step <= step + 1'd1;
                  end
              end

              ValidateSeq: begin
                  if (reset_step == 2600) begin
                      stage <= WaitTriggerRelease;
                      seq_trigger <= 1'b0;
                      reset_step <= 0;
                  end else begin
                      reset_step <= reset_step + 1'd1;
                  end
              end

              WaitTriggerRelease: begin
                  if (update_frame == 1'b0)
                      stage <= WaitTrigger;
              end
          endcase
      end
    end

endmodule

