module menu_screen #(
    parameter MAX_POS = 109
)(
    input  wire enable,
    input  wire [7:0] i_red_intensity,
    input  wire [7:0] i_blue_intensity,
    input  wire [7:0] i_green_intensity,
    input  wire red_ready_to_play,
